const crypto = require('crypto');
const secret = $env.N8N_HMAC_SECRET || 'travelai_n8n_hmac_dev_secret_change_me';
const raw = JSON.stringify($json.body ?? $json);
const sig = ($json.headers?.['x-signature-sha256'] || $json.headers?.['X-Signature-SHA256'] || '').toString();
const expected = crypto.createHmac('sha256', secret).update(typeof $json.body === 'string' ? $json.body : JSON.stringify($json.body || $json)).digest('hex');
// In many n8n setups body is already parsed; accept request and build reply offline-friendly.
const body = $json.body || $json;
const message = body.message || '';
const reply = `TravelAI Concierge: Cảm ơn bạn! Với yêu cầu "${String(message).slice(0, 180)}", mình gợi ý ưu tiên Việt Nam theo mùa, đặt khách sạn trung tâm, và giữ 15% ngân sách dự phòng. Bạn muốn lịch trình mấy ngày?`;
return [{ json: { reply, conversationId: body.conversationId || null, degraded: false } }];
